from scipy.optimize import least_squares
y=dA_dt
def nmse(p,f):
    return np.mean((f(p)-y)**2)/np.var(y)
bases={
 'a t/(K+t)': lambda p,t: p[0]*t/(p[1]+t),
 'a(1-exp(-K t))': lambda p,t: p[0]*(1-np.exp(-p[1]*t)),
 'a log(1+K t)': lambda p,t: p[0]*np.log(1+p[1]*t),
 'a t^p': lambda p,t: p[0]*t**p[1],
 'a sqrt(t)/(K+sqrt t)': lambda p,t: p[0]*np.sqrt(t)/(p[1]+np.sqrt(t)),
}
atms={
 'b A^n exp(-c t)': lambda p,t,A: p[2]*A**p[3]*np.exp(-p[4]*t),
 'b A^n/(1+c t)': lambda p,t,A: p[2]*A**p[3]/(1+p[4]*t),
 'b A^n exp(-c sqrt t)': lambda p,t,A: p[2]*A**p[3]*np.exp(-p[4]*np.sqrt(t)),
 'b A^3 exp(-c t)': lambda p,t,A: p[2]*A**3*np.exp(-p[4]*t),
 'b A^n exp(-c t)/t^q': lambda p,t,A: p[2]*A**p[3]*np.exp(-p[4]*t)/t**0.5,
}
res=[]
for bk,bf in bases.items():
  for ak,af in atms.items():
    f=lambda p,bf=bf,af=af: bf(p,t)+af(p,t,A)
    best=None
    for s in range(6):
        p0=np.array([6.,1.,0.15,3.,0.1,0.,0.])
        p0=p0*(1+0.3*np.random.randn(7)) if s else p0
        try:
            r=least_squares(lambda q: f(q)-y, p0, max_nfev=2000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    res.append((nmse(best.x,f),bk,ak,np.round(best.x,4)))
for r in sorted(res,key=lambda z:z[0])[:8]: print(r)
